    /* 响应式设计 */
    @media (max-width: 600px) {
      .choice-container {
        max-width: 90%;
      }

      .choice-toggle {
        font-size: 14px;
        padding: 12px 15px;
      }

      .choice-item {
        font-size: 13px;
