        }

        @keyframes spiderMove {
            0% {
                top: 0;
                left: 0;
                transform: rotate(0deg);
            }
            25% {
                top: 0;
                left: calc(100% - 24px);
                transform: rotate(90deg);
            }
            50% {
                top: calc(100% - 24px);
                left: calc(100% - 24px);
                transform: rotate(180deg);
            }
            75% {
                top: calc(100% - 24px);
                left: 0;
                transform: rotate(270deg);
            }
            100% {
                top: 0;
                left: 0;
                transform: rotate(360deg);
