<style>
    :root {
        --bunny-pink: #ffdae9;
        --bunny-dark-pink: #ffadd2;
        --bunny-text: #85586f;
        --bunny-white: #fff0f5;
        --bunny-accent: #b7e4c7; /* 嫩草绿 */
    }

    /* 容器样式 */
    details.bunny-container {
        font-family: "Varela Round", "Microsoft YaHei", sans-serif;
        max-width: 450px;
        margin: 20px auto;
        background-color: var(--bunny-white);
        border: 4px dashed var(--bunny-dark-pink);
        border-radius: 20px;
        padding: 15px;
        color: var(--bunny-text);
        position: relative;
        box-shadow: 0 8px 0 rgba(255, 173, 210, 0.4);
        outline: none;
    }

    /* 装饰性兔耳朵 */
    details.bunny-container::before, details.bunny-container::after {
        content: '';
        position: absolute;
        top: -25px;
        width: 30px;
        height: 60px;
        background: var(--bunny-white);
        border: 4px solid var(--bunny-dark-pink);
        border-bottom: none;
        border-radius: 20px 20px 0 0;
        z-index: -1;
    }
    details.bunny-container::before { left: 40px; transform: rotate(-10deg); }
    details.bunny-container::after { right: 40px; transform: rotate(10deg); }

    /* 1. 顶部信息栏 (修改点：flex-direction: column 实现纵向排列) */
    summary.header-info {
        display: flex;
        flex-direction: column; /* 关键修改：纵向排列 */
        gap: 5px;               /* 增加两行之间的间距 */
        background: var(--bunny-pink);
        padding: 8px 12px;
        border-radius: 12px;
        font-size: 13px;
        font-weight: bold;
        margin-bottom: 12px;
        cursor: pointer;
        list-style: none;
        position: relative;
        z-index: 10;
        transition: background 0.3s;
    }

    summary.header-info::-webkit-details-marker {
        display: none;
    }

    summary.header-info:hover {
        background: var(--bunny-dark-pink);
        color: white;
    }

    details.bunny-container:not([open]) summary.header-info {
        margin-bottom: 0;
    }

    /* 2. 内心想法 (气泡风格) */
    .thought-bubble {
        background: #fff;
        border: 2px solid var(--bunny-accent);
        padding: 10px;
        border-radius: 15px;
        position: relative;
        margin-bottom: 15px;
        font-size: 13px;
    }
    .thought-bubble::after {
        content: '';
        position: absolute;
        bottom: -8px;
        left: 20px;
        width: 10px;
        height: 10px;
        background: #fff;
        border-bottom: 2px solid var(--bunny-accent);
        border-right: 2px solid var(--bunny-accent);
        transform: rotate(45deg);
    }
    .label-tag {
        display: inline-block;
        background: var(--bunny-accent);
        color: #fff;
        padding: 2px 6px;
        border-radius: 4px;
        font-size: 10px;
        margin-bottom: 4px;
    }

    /* 3. 弹幕区 */
    .danmaku-box {
        background: #2b2d42;
        border-radius: 10px;
        padding: 10px;
        height: 80px;
        overflow: hidden;
        position: relative;
        margin-bottom: 15px;
        border: 2px solid var(--bunny-dark-pink);
    }
    .danmaku-title {
        position: absolute;
        top: 0; left: 0;
        background: var(--bunny-dark-pink);
        color: white;
        font-size: 10px;
        padding: 2px 5px;
        border-bottom-right-radius: 8px;
        z-index: 2;
    }
    .danmaku-text {
        color: #fff;
        font-size: 12px;
        white-space: nowrap;
        animation: scrollText 8s linear infinite;
        margin-bottom: 6px;
        text-shadow: 1px 1px 0 #ff0066;
    }
    .d1 { animation-delay: 0s; color: #ff99c8; }
    .d2 { animation-delay: 2s; color: #a9def9; }
    .d3 { animation-delay: 4s; color: #fcf6bd; }

    @keyframes scrollText {
        0% { transform: translateX(100%); }
        100% { transform: translateX(-150%); }
    }

    /* 4. 额外板块 */
    details.extra-section {
        background: rgba(255, 255, 255, 0.5);
        border-radius: 10px;
        padding: 5px;
    }
    details.extra-section > summary {
        cursor: pointer;
        font-size: 13px;
        color: var(--bunny-dark-pink);
        font-weight: bold;
        list-style: none;
    }
    details.extra-section > summary::before { content: '💖'; margin-right: 5px; }

</style>
</head>
<body>

<details class="bunny-container">
    <!-- 1. 时间地点 (纵向排列) -->
    <summary class="header-info">
        <span>🕒 时间: $1</span>
        <span>📍 地点: $2</span>
    </summary>

    <!-- 2. 内心想法 -->
    <div class="thought-bubble">
