            else if (mode === 'fortune') {
                // --- 全新：为 fortune 万年历模式构建DOM ---
                const cardInfo = (lines[0] || ' - ').split(' - ');
                const cardNumber = cardInfo[0].trim();
                const cardName = cardInfo[1] ? cardInfo[1].trim() : '';
                const cardKeywords = lines[1] || '...';
                const cardMeaning = lines[2] || '...';
