<body>
    <div class="succubus-skill-panel">
        <div class="panel-frame">
            <div class="theme-toggle-btn" onclick="togglePanelTheme(this)">☀️</div>
            <div class="panel-title">⚜️ 淫纹技能刻印 ⚜️</div>
            <div class="skill-container">
                <!-- 选项1 -->
                <div class="skill-card" onclick="toggleSelection(this)">
                    <div class="skill-head">
                        <span class="skill-icon">🤍</span>
                        <span class="skill-name">$1</span>
                    </div>
                    <!-- 将描述放入单独的类以便JS抓取 -->
                    <div class="skill-desc">$2</div>
                    <div class="skill-buff">$3</div>
                </div>
                <!-- 选项2 -->
                <div class="skill-card" onclick="toggleSelection(this)">
                    <div class="skill-head">
                        <span class="skill-icon">💜</span>
                        <span class="skill-name">$4</span>
                    </div>
                    <div class="skill-desc">$5</div>
                    <div class="skill-buff">$6</div>
                </div>
                <!-- 选项3 -->
                <div class="skill-card" onclick="toggleSelection(this)">
                    <div class="skill-head">
                        <span class="skill-icon">⛓️</span>
                        <span class="skill-name">$7</span>
                    </div>
                    <div class="skill-desc">$8</div>
                    <div class="skill-buff">$9</div>
                </div>
            </div>
            <button class="confirm-btn" id="confirmSkillBtn" onclick="submitSkills()">确认刻印</button>

            <div class="loading-overlay" id="loadingOverlay">
                <div class="spinner">🔮</div>
                <div id="loadingText">正在读取灵脉...</div>
            </div>
        </div>
    </div>

    <script>
        // ================= 配置区域 =================
        const targetFile = "😈魅魔世界书❤️"; // 请替换为你的世界书文件名(无后缀)
        const targetUid = "14";              // 请替换为用于存储数据的条目UID
        // ===========================================
        const charName = "{{char}}"; // 自动获取当前角色名
        function togglePanelTheme(btn) {
            const container = btn.closest('.succubus-skill-panel');
            container.classList.toggle('light-mode');
            const isLight = container.classList.contains('light-mode');
            btn.innerText = isLight ? '🌙' : '☀️';
        }
        function toggleSelection(card) {
            card.classList.toggle('selected');
            updateBtnState();
        }
        function updateBtnState() {
            const selected = document.querySelectorAll('.succubus-skill-panel .skill-card.selected');
            const btn = document.getElementById('confirmSkillBtn');
            if (selected.length > 0) {
                btn.classList.add('active');
                btn.innerText = `确认刻印 (${selected.length})`;
            } else {
                btn.classList.remove('active');
                btn.innerText = "请选择技能";
            }
        }
        async function submitSkills() {
            if (typeof triggerSlash !== 'function') {
                alert("请在酒馆环境中使用。");
                return;
            }
            // 1. 获取选中数据
            const cards = document.querySelectorAll('.succubus-skill-panel .skill-card.selected');
            let skillTextArr = [];
            cards.forEach(c => {
                const name = c.querySelector('.skill-name').innerText;
                const desc = c.querySelector('.skill-desc').innerText;
                const buff = c.querySelector('.skill-buff').innerText;
                // 格式化新技能文本
                skillTextArr.push(`- 【${name}】：${desc} (${buff})`);
            });
            const newSkillsBlock = skillTextArr.join('\n');
            // 2. 显示Loading
            const overlay = document.getElementById('loadingOverlay');
            const loadingText = document.getElementById('loadingText');
            overlay.classList.add('show');
            try {
                // 3. 读取现有WI内容
                // 注意：这里需要ST支持 triggerSlash 返回值。
                loadingText.innerText = `正在连接 ${charName} 的记录...`;
                const oldContent = await triggerSlash(`/getentryfield file="${targetFile}" field=content ${targetUid}`);

                // 4. 正则处理：查找是否已有该角色的区块
                // 区块格式定义： ### 角色名 的技能 ### ... ###
                const regionStart = `### ${charName} 的技能 ###`;
                const regionEnd = `### End ${charName} ###`;
                const regex = new RegExp(`${regionStart}([\\s\\S]*?)${regionEnd}`, 'i');

                let finalContent = "";

                if (oldContent.includes(regionStart)) {
                    // 如果已存在该角色的区块，则在该区块内部追加
                    // 为了简单起见，我们替换掉整个区块为 旧内容 + 新内容
                    finalContent = oldContent.replace(regex, (match, p1) => {
                        return `${regionStart}${p1.trim()}\n${newSkillsBlock}\n${regionEnd}`;
                    });
                } else {
                    // 如果不存在，追加到文末
                    // 确保旧内容存在，如果是undefined则置空
                    const safeOldContent = (oldContent && oldContent !== "undefined" && oldContent !== "null") ? oldContent : "";
                    finalContent = `${safeOldContent}\n\n${regionStart}\n${newSkillsBlock}\n${regionEnd}`;
                }

                // 5. 写入WI
                loadingText.innerText = "正在刻印淫纹...";
                // 必须对 finalContent 进行转义防止 JSON 格式错误，但 triggerSlash 传参通常比较宽容
                // 在这里我们简单处理，如果有换行符等复杂情况推荐 base64，但ST可以直接传
                // 为了避免管道符冲突，可以使用 setentryfield ... contents

                // 构造 ST Script 写入整个拼接后的字符串
                // 注意：如果内容过长可能会超出命令行限制，如有问题请分段，但一般够用。
                await triggerSlash(`/setentryfield file="${targetFile}" uid=${targetUid} field=content ${finalContent}`);

                // 6. 成功反馈
                triggerSlash(`/echo severity=success 刻印完成！数据已保存至 [${targetFile}] 条目。`);
                overlay.classList.remove('show');
                document.querySelector('.panel-frame').style.opacity = '0.5';
                document.getElementById('confirmSkillBtn').innerText = "刻印完成";

            } catch (e) {
                console.error(e);
                loadingText.innerText = "刻印失败，请查看控制台";
                setTimeout(() => overlay.classList.remove('show'), 2000);
            }
        }
    </script>
</body>
</html>
