                    if (idx % 2 === 1) {
                        html += `<span class="novel-cp-relation">${part.trim()}</span>`;
                    } else {
                        html += `<span class="novel-cp-name">${part.trim()}</span>`;
                    }
                });
                return html;
            }

            let contentHTML = '';

            // CP Row
            if (cpGroups.length > 0) {
                const cpHTML = cpGroups.map(g => `<div class="novel-cp-group">${parseCPGroup(g)}</div>`).join('<span style="opacity:0.3; margin:0 5px">/</span>');
                contentHTML += `
                    <div class="novel-meta-row">
                        <div class="novel-meta-item">
                            <span class="novel-meta-label">Couple</span>
                            ${cpHTML}
                        </div>
                    </div>`;
            }

            // Location Row
            if (locRaw) {
                contentHTML += `
                    <div class="novel-meta-row">
                        <div class="novel-meta-item">
                            <span class="novel-meta-label">Location</span>
                            <span>${locRaw}</span>
                        </div>
                    </div>`;
            }

            metaContainer.innerHTML = contentHTML;

            // 4. 渲染标签
            const tagsContainer = container.querySelector('#novel-tags-container');
            if (tagsContainer) {
                const tagsRaw = tagsContainer.getAttribute('data-tags') || '';
                const tags = tagsRaw.split(/[\/，,]/).map(t => t.trim()).filter(t => t);
                tagsContainer.innerHTML = '';
                tags.forEach(tag => {
                    const span = document.createElement('span');
                    span.className = 'novel-tag';
                    span.textContent = tag;
                    tagsContainer.appendChild(span);
                });
            }
        })();
    </script>
</div>
</body>
</html>
