                           const lifeG = grid3([{l:'当前渴求', v:cWant}, {l:'隐秘心思', v:cBeneath}, {l:'状态表现', v:cNow}]);
                           const ini = /<initiative[^>]*type=["']([^"']*)["'][^>]*>([\s\S]*?)<\/initiative>/i.exec(c);

                           npcHTML += `<div class="npc-item"><div class="npc-top" onclick="this.parentElement.classList.toggle('collapsed')"><span class="n-name">${name}</span>${getTag(c, 'identity') ? `<span class="n-id">${getTag(c, 'identity')}</span>` : ''}</div>${show('核心特征', getTag(c, 'profile'))}${show('关系阶段', rel || getTag(c, 'relation_stage'))}${show('当前情绪', emo || getTag(c, 'emotion'))}${cbH || show('认知边界', getTag(c, 'cognition'))}${impH}${lifeG}${resH}${show('行动韧性', getTag(c, 'persist'))}${show('即时反应', getTag(c, 'beat'))}${ini ? `<div class="row"><span class="r-l">交互思维</span><span class="r-v"><span class="n-name" style="font-size:0.85em;padding:1px 6px;margin-right:8px;">${ini[1]}</span>${ini[2]}</span></div>` : ''}${show('后续动向', getTag(c, 'handoff'))}</div>`;
                       }
                       // 2.5 群体角色
                       let grpR = /<group[^>]*name=["']([^"']*)["'][^>]*>([\s\S]*?)<\/group>/gi; let g;
                       while ((g = grpR.exec(sdA))) {
                           const c = g[2], name = g[1], iden = getTag(c, 'identity');
                           const cbTag = /<cognitive_boundary[^>]*known=["']([^"']*)["'][^>]*unknown=["']([^"']*)["'][^>]*\/>/i.exec(c);
                           const cbH = cbTag ? `<div class="row"><span class="r-l">认知边界</span><span class="r-v"><span class="n-name" style="font-size:0.8em;padding:1px 6px;margin-right:4px;">已知</span>${cbTag[1]}<br><span class="n-name" style="font-size:0.8em;padding:1px 6px;margin-right:4px;margin-top:4px;display:inline-block">未知</span>${cbTag[2]}</span></div>` : null;
                           npcHTML += `<div class="npc-item"><div class="npc-top" onclick="this.parentElement.classList.toggle('collapsed')"><span class="n-name">${name}</span><div style="display:flex;gap:4px;align-items:center;margin-left:auto">${iden ? `<span class="n-id">${iden}</span>` : ''}<span class="n-name" style="font-size:0.75em;padding:1px 6px;background:var(--bg-tag);flex-shrink:0">群体</span></div></div>${show('群体目标', getTag(c, 'group_want'))}${cbH || show('认知边界', getTag(c, 'cognitive_boundary'))}${show('行为动态', getTag(c, 'behavior'))}${show('后续动向', getTag(c, 'next_tendency'))}</div>`;
