                               const cbTag = /<cognitive_boundary[^>]*known=["']([^"']*)["'][^>]*unknown=["']([^"']*)["'][^>]*\/>/i.exec(c);
                               if (cbTag) cbH = `<div class="row"><span class="r-l">认知边界</span><span class="r-v"><span class="n-name" style="font-size:0.8em;padding:1px 6px;margin-right:4px;">已知</span>${cbTag[1]}<br><span class="n-name" style="font-size:0.8em;padding:1px 6px;margin-right:4px;margin-top:4px;display:inline-block">未知</span>${cbTag[2]}</span></div>`;

