document.addEventListener('DOMContentLoaded', () => {
    const forumContainer = document.querySelector('.forum-container');
    const postDetailView = document.querySelector('.post-detail-view');
    const backButton = document.querySelector('.back-button');

    // 帖子列表和详情页的DOM元素
    const detailTitle = document.getElementById('detail-title');
    const detailAuthor = document.getElementById('detail-author');
    const detailTime = document.getElementById('detail-time');
    const detailBody = document.getElementById('detail-body');
    const commentCountHeader = document.getElementById('comment-count');
    const commentList = document.getElementById('comment-list');

    const postList = document.querySelector('.post-list');

    // 使用事件委托来处理帖子点击
    postList.addEventListener('click', (event) => {
        const postItem = event.target.closest('.post-item');
        if (!postItem) return;

        // 1. 从data属性和隐藏div中获取帖子数据
        const title = postItem.dataset.title;
        const author = postItem.dataset.author;
        const time = postItem.dataset.time;
        const body = postItem.dataset.body; 
        const commentsCount = postItem.dataset.commentsCount;
        // 修改：现在commentsRawHtml是已渲染的HTML
        const commentsRawHtml = postItem.querySelector('.post-comments-data').innerHTML;

        // 2. 填充帖子详情页内容
        detailTitle.textContent = title;
        detailAuthor.textContent = author;
        detailTime.textContent = time;
        detailBody.textContent = body;
        commentCountHeader.textContent = `全部评论 (${commentsCount})`;

        // 3. 修改：直接设置commentList.innerHTML = commentsRawHtml; 无需解析
        commentList.innerHTML = commentsRawHtml;

        // 如果没有评论，显示提示
        if (commentList.children.length === 0) {
    commentList.innerHTML = '<p class="no-comment-placeholder" style="color: #888; text-align: center;">暂无评论，快来抢沙发吧！</p>';
}

        // 4. 切换视图
        showDetailView();
    });

    // 返回按钮事件
    backButton.addEventListener('click', () => {
        showListView();
    });

    // 显示详情页
    function showDetailView() {
        forumContainer.classList.add('hidden');
        postDetailView.classList.remove('hidden');
        window.scrollTo(0, 0); // 切换后滚动到页面顶部
    }

    // 显示列表页
    function showListView() {
        forumContainer.classList.remove('hidden');
        postDetailView.classList.add('hidden');
    }

// 搜索功能实现
    const searchInput = document.querySelector('.search-bar input');
    const searchButton = document.querySelector('.search-bar button');

    function performSearch() {
        const query = searchInput.value.trim(); // 获取并清理输入内容
        if (query) { // 检查内容是否为空
            const message = `搜索帖子:${query}`;
            console.log("即将发送响应:", message); // 用于在浏览器控制台调试

            // 检查 triggerSlash 函数是否存在，然后调用它
            if (typeof triggerSlash === 'function') {
                // 使用您提供的参考格式发送响应
                triggerSlash(`/send ${message}|/trigger`);
            } else {
                console.error("triggerSlash 函数未定义！");
            }

            // 可选：清空输入框
            // searchInput.value = ''; 
        }
    }

    // 监听搜索按钮的点击事件
    searchButton.addEventListener('click', performSearch);

    // 监听在输入框中按回车键的事件
    searchInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
            event.preventDefault(); // 阻止表单默认的回车提交行为
            performSearch();
        }
    });


/**
     * 在界面上动态添加一条新评论并更新计数
     * @param {string} author - 评论作者
     * @param {string} text - 评论内容
     */
    function addCommentToUI(author, text) {
        // 1. 检查并移除“暂无评论”的提示
        const noCommentMsg = commentList.querySelector('.no-comment-placeholder');
        if (noCommentMsg) {
            noCommentMsg.remove();
        }

        // 2. 创建新的评论元素
        const commentItem = document.createElement('div');
        commentItem.className = 'comment-item';

        const authorSpan = document.createElement('span');
        authorSpan.className = 'author';
        authorSpan.textContent = author;

        const textDiv = document.createElement('div');
        textDiv.className = 'text';
        textDiv.textContent = text;

        commentItem.appendChild(authorSpan);
        commentItem.appendChild(textDiv);

        // 3. 将新评论添加到列表中
        commentList.appendChild(commentItem);

        // 4. 更新评论总数
        const countMatch = commentCountHeader.textContent.match(/\((\d+)\)/);
        if (countMatch && countMatch[1]) {
            let currentCount = parseInt(countMatch[1], 10);
            commentCountHeader.textContent = `全部评论 (${currentCount + 1})`;
        }

        // 5. (可选但推荐) 滚动到新评论的位置，让用户能看到
        commentItem.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }



 // 评论发布功能实现
    const commentForm = document.getElementById('comment-form');

    commentForm.addEventListener('submit', (event) => {
        event.preventDefault(); // 阻止表单默认的页面刷新行为

        const commentInput = commentForm.querySelector('input');
        const commentText = commentInput.value.trim();

        // 从详情页获取当前帖子的标题
        const postTitle = document.getElementById('detail-title').textContent;
	const user = "我"; 


        if (commentText) { // 确保评论内容不为空
            const message = `{{user}}在帖子${postTitle}发布评论:${commentText}`;
            console.log("即将发送响应:", message); // 用于在浏览器控制台调试

            // 检查 triggerSlash 函数是否存在，然后调用它
            if (typeof triggerSlash === 'function') {
                // 使用您提供的参考格式发送响应
                triggerSlash(`/send ${message}|/trigger`);
            } else {
                console.error("triggerSlash 函数未定义！");
            }



        addCommentToUI(user, commentText); // 调用函数，立即更新UI


            // 发布成功后清空输入框
            commentInput.value = '';
        }
    });

// ===== 新增：发布帖子弹窗逻辑 =====
    const addPostBtn = document.querySelector('.add-post-btn');
    const postModal = document.getElementById('post-modal');
    const cancelPostBtn = document.getElementById('cancel-post-btn');
    const publishPostBtn = document.getElementById('publish-post-btn');
    const newPostTitleInput = document.getElementById('new-post-title');
    const newPostContentInput = document.getElementById('new-post-content');

    // 打开弹窗
    addPostBtn.addEventListener('click', () => {
        postModal.classList.remove('hidden');
    });

    // 关闭弹窗的函数
    function closeModal() {
        postModal.classList.add('hidden');
        // 清空输入内容
        newPostTitleInput.value = '';
        newPostContentInput.value = '';
    }

    // 点击取消按钮或灰色背景区域关闭弹窗
    cancelPostBtn.addEventListener('click', closeModal);
    postModal.addEventListener('click', (event) => {
        // 检查点击的是否是背景本身
        if (event.target === postModal) {
            closeModal();
        }
    });

    // 点击发布按钮
    publishPostBtn.addEventListener('click', () => {
        const title = newPostTitleInput.value.trim();
        const content = newPostContentInput.value.trim();

        if (!title || !content) {
            alert('标题和内容都不能为空！');
            return;
        }

        // 构造要发送的消息
        const message = `发布帖子:${title} ${content}`;
        console.log("即将发送响应:", message); // 控制台调试

        // 检查并调用 triggerSlash 函数
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/send ${message}|/trigger`);
        } else {
            console.error("triggerSlash 函数未定义！");
        }

        // 关闭弹窗
        closeModal();
    });



});
</script>

</body>
</html>
