  <title>SillyTavern Choice Menu</title>
  <style>
    /* 引入字体 */
    @import url('https://fonts.googleapis.com/css2?family=M+PLUS+Rounded+1c:wght@400;700&family=Noto+Sans+SC:wght@400;700&display=swap');

    /* 选择框容器 */
    .choice-container {
      position: relative;
      width: 100%;
      max-width: 500px;
      margin: 20px auto;
      font-family: 'M PLUS Rounded 1c', 'Noto Sans SC', sans-serif;
      color: #BEA5D6; /* 紫调文字 */
    }

    /* 切换按钮 */
    .choice-toggle {
      background: #2C2A4A; /* 深紫背景 */
      border: 2px solid #8A6EAF; /* 较亮的紫色边框 */
      padding: 14px 20px;
      border-radius: 20px;
      text-align: center;
      cursor: pointer;
      font-size: 16px;
      font-weight: 600;
      color: #BEA5D6; /* 紫调文字 */
      transition: all 0.3s ease;
      box-shadow: 0 3px 15px rgba(147, 112, 219, 0.2); /* 紫色辉光 */
      position: relative;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .choice-toggle:hover {
      background: #403D64; /* 稍亮的深紫hover效果 */
      transform: scale(1.05) translateY(-3px);
    }

    .choice-toggle::before,
    .choice-toggle::after {
      content: '🌙'; /* 弯月 emoji */
      font-size: 14px;
      color: #8A6EAF;
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
    }

    .choice-toggle::before {
      left: 20px; /* 靠近文本 */
    }

    .choice-toggle::after {
      right: 20px; /* 靠近文本 */
    }

    /* 菜单容器 */
    .choice-menu {
      display: none;
      background: linear-gradient(to bottom, #2C2A4A, #5B4B84); /* 深紫渐变 */
      border: 2px solid #8A6EAF; /* 较亮的紫色边框 */
      border-radius: 16px;
      margin-top: 10px;
      padding: 12px 12px 20px 12px; /* 底部增加空间 */
      box-shadow: 0 4px 15px rgba(147, 112, 219, 0.2); /* 紫色辉光 */
      animation: bounceIn 0.4s ease-out;
      position: relative; /* 为星星定位 */
    }

    /* 菜单下方的星星 */
    .choice-menu::before {
      content: '✦'; /* 星星 */
      position: absolute;
      bottom: 3px; /* 拉开距离 */
      left: 50%;
      transform: translateX(-50%);
      font-size: 15px;
      color: #8A6EAF;
      animation: starFlash 1.2s infinite;
      z-index: 10; /* 确保不被覆盖 */
    }

    /* 菜单展开动画 */
    @keyframes bounceIn {
      0% {
        opacity: 0;
        transform: scale(0.8) translateY(-20px);
      }
      60% {
        transform: scale(1.05);
      }
      100% {
        opacity: 1;
        transform: scale(1) translateY(0);
      }
    }

    /* 菜单项 */
    .choice-item {
      padding: 12px 20px 12px 14px;
      margin: 6px 0;
      background: #2C2A4A; /* 深紫背景 */
      border: 1px solid #8A6EAF; /* 较亮的紫色边框 */
      border-radius: 12px;
      cursor: pointer;
      font-size: 16px;
      font-weight: 500;
      color: #BEA5D6; /* 紫调文字 */
      transition: all 0.3s ease;
      position: relative;
    }

    .choice-item:hover {
      background: #403D64; /* 稍亮的深紫hover效果 */
      border-color: #BEA5D6; /* 更亮的紫色边框 */
      transform: translateX(8px) scale(1.03);
    }

    /* 星星闪烁变色动画 */
    @keyframes starFlash {
      0%, 100% {
        color: #8A6EAF;
      }
      70% {
        color: #DFDFFB; /* 更亮的淡紫色，增加对比 */
      }
    }

    /* 响应式设计 */
    @media (max-width: 600px) {
      .choice-container {
        max-width: 90%;
      }

      .choice-toggle {
        font-size: 14px;
        padding: 12px 15px;
      }

      .choice-item {
        font-size: 13px;
        padding: 10px 15px;
      }

      .choice-toggle::before,
      .choice-toggle::after,
      .choice-menu::before {
        font-size: 12px;
      }

      .choice-toggle::before {
        left: 15px;
      }

      .choice-toggle::after {
        right: 15px;
      }

      .choice-menu::before {
        bottom: 4px; /* 移动端调整星星位置 */
      }
    }

    /* 菜单展开时的样式 */
    .choice-menu.active {
      display: block;
    }
  </style>
</head>
<body>
  <!-- SillyTavern 将替换 <choice> 为以下结构，$1 到 $5 为外部正则捕获内容 -->
  <div class="choice-container">
    <div class="choice-toggle">选择你的行动吧~♫</div>
    <div class="choice-menu">
      <div class="choice-item" data-choice="$1">$1</div>
      <div class="choice-item" data-choice="$2">$2</div>
      <div class="choice-item" data-choice="$3">$3</div>
      <div class="choice-item" data-choice="$4">$4</div>
      <div class="choice-item" data-choice="$5">$5</div>
    </div>
  </div>

  <script>
    // 添加交互逻辑
    document.querySelectorAll('.choice-toggle').forEach(toggle => {
      toggle.addEventListener('click', () => {
        const menu = toggle.nextElementSibling;
        menu.classList.toggle('active');
      });
    });

    document.querySelectorAll('.choice-item').forEach(item => {
      item.addEventListener('click', async () => {
        const choiceText = item.getAttribute('data-choice');
        await triggerSlash(`/setinput ${choiceText}`);
        // 隐藏菜单
        item.parentElement.classList.remove('active');
      });
    });
  </script>
</body>
</html>
