    }

    if (modifiedCount > 0) {
      await replaceTavernRegexes(allRegexes, {});
devLog(`[FilterGroup] 成功更新 ${modifiedCount} 个正则表达式的状态。`);
      return true;
    }

    return false;
  } catch (error) {
    console.error('[FilterGroup] 应用状态变更失败:', error);
    return false;
  }
}

