        if (parentDoc && parentDoc !== document) {
            docContext = parentDoc;
            console.log('Font Manager: Operating in parent document context.');
        } else {
            console.log('Font Manager: Operating in current document context.');
        }
    } else {
        console.log('Font Manager: Operating in current document context.');
    }
} catch (e) {
    console.warn('Font Manager: Unable to access parent document (possibly cross-origin). Falling back to current document.', e);
}

