                        <div class="h-group"><label class="h-label">API URL</label><input id="h-url" class="h-input" value="${state.apiUrl}" placeholder="https://api.openai.com/v1"></div>
                        <div class="h-group"><label class="h-label">API Key</label><input id="h-key" class="h-input" type="password" value="${state.apiKey}"></div>
