                </div>
            </div>
        `;
        $('body').append(html);

        $('.h-close, #hajimi-ui-overlay').on('click', function(e) { if(e.target===this || $(this).hasClass('h-close')) $('#hajimi-ui-overlay').remove(); });
        $('.h-tab').on('click', function() { $('.h-tab,.h-body').removeClass('active'); $(this).addClass('active'); $('#tab-'+$(this).data('tab')).addClass('active'); });
        $('.h-mode-card').on('click', function() { $('.h-mode-card').removeClass('selected'); $(this).addClass('selected'); state.mode=$(this).data('val'); });
        $('#btn-cn').on('click', function() { $('.h-lang-btn').removeClass('active'); $(this).addClass('active'); $('#h-out').val(currentResult.cn||""); });
        $('#btn-en').on('click', function() { $('.h-lang-btn').removeClass('active'); $(this).addClass('active'); $('#h-out').val(currentResult.en||""); });

        const renderList = () => {
            const list = $('#h-list').empty();
            if(!state.history.length) return list.html('<div style="text-align:center;padding:20px;color:#7A6040">暂无记录</div>');
            state.history.forEach(i => {
                const icon = i.mode==='human'?ICONS.human:ICONS.pro;
                const el = $(`<div class="h-history-item"><div class="h-icon-box">${icon}</div><div style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${i.raw}</div></div>`);
                el.on('click', () => { $('#h-in').val(i.raw); currentResult={cn:i.rcn,en:i.ren}; $('#btn-cn').click(); $('.h-tab[data-tab="gen"]').click(); 
                $('.h-mode-card').removeClass('selected'); $(`.h-mode-card[data-val="${i.mode}"]`).addClass('selected'); state.mode=i.mode; });
                list.append(el);
            });
        };
        renderList();

        $('#h-fetch').on('click', async () => {
            const u=$('#h-url').val().replace(/\/$/,''), k=$('#h-key').val();
            if(!u || !k) return alert('请先填写 URL 和 Key');
            try { const r=await fetch(`${u}/models`,{headers:{'Authorization':`Bearer ${k}`}}); const d=await r.json(); 
            if(d.data) { const s=$('#h-model').empty(); d.data.forEach(m=>s.append(`<option value="${m.id}">${m.id}</option>`)); if(state.model)s.val(state.model); }
            } catch(e) { alert(e.message); }
        });
        $('#h-save').on('click', () => { state.apiUrl=$('#h-url').val(); state.apiKey=$('#h-key').val(); state.model=$('#h-model').val(); saveState(); alert('已保存'); });

        $('#h-go').on('click', async () => {
            const raw=$('#h-in').val(); if(!raw) return;
            if(!state.apiUrl || !state.apiKey) return alert('请前往配置页填写 API URL 和 Key！');
            $('#h-go').text('生成中...').prop('disabled',true);

            const sys = state.mode==='human' 
                ? `You are a precise prompt refining assistant. Task: Summarize ALL points and details from the user's request, expand moderately, and generate a concise, easy-to-understand prompt. Rules: 1. Cover ALL user requirements (summarize & expand). 2. Be CONCISE and PRECISE. Avoid wordiness. 3. Use natural language suitable for AI generation. 4. Output ONLY the raw prompt content. No "Role:" labels. 5. JSON Format: { "cn": "...", "en": "..." }`
                : `You are a Senior UI/UX Designer & Prompt Engineer. Task: Extract core needs and details, refining them into a PROFESSIONAL UI DESIGN PROMPT. Rules: 1. QUANTIFY inputs using professional terminology (Visual Hierarchy, Grid, Hex Codes, Padding, Typography, Texture). 2. ABSOLUTELY FORBIDDEN: Short/Single-sentence outputs. 3. If user input is sparse/vague, YOU MUST EXPAND IT with relevant professional details (add matching colors, layout styles, textures) to make it complete. 4. Focus on structure, layout, and visual properties. 5. OUTPUT ONLY RAW DATA. NO labels. 6. JSON Format: { "cn": "...", "en": "..." }`;

            const msgs = [{role:'system',content:sys},{role:'user',content:raw}];
            try {
                const r = await fetch(`${state.apiUrl.replace(/\/$/,'')}/chat/completions`, {
                    method:'POST', headers:{'Content-Type':'application/json','Authorization':`Bearer ${state.apiKey}`},
                    body: JSON.stringify({model:state.model||'gpt-3.5-turbo', messages:msgs})
                });
                const d=await r.json();
                let txt = d.choices?.[0]?.message?.content;
                if(!txt) throw new Error("API No Content");

                const parse = (t) => { try{return JSON.parse(t)}catch(e){const m=t.match(/\{[\s\S]*\}/);if(m)return JSON.parse(m[0]);throw e;} };
                const safeStr = (v) => (typeof v==='object'&&v)?JSON.stringify(v,null,2).replace(/[\{\}\"]/g,'').trim():v;

                const j = parse(txt);
                currentResult = { cn: safeStr(j.cn)||"Error CN", en: safeStr(j.en)||"Error EN" };

                $('#btn-cn').click();
                state.history.unshift({raw, rcn:currentResult.cn, ren:currentResult.en, mode:state.mode});
                if(state.history.length>30) state.history.pop(); saveState(); renderList();
            } catch(e) { alert('错误: '+e.message); }
            $('#h-go').html(`${ICONS.star} 立点击生成 `).prop('disabled',false);
        });
    }

    function init() {
        const $ = getJQuery(); if(!$) return setTimeout(init, 500);
        const menu = $('#extensionsMenu'); if(!menu.length) return setTimeout(init, 500);

        deepClean();
        const btn = $(`<a id="hajimi-trigger-btn" class="list-group-item" href="#" title="提示词生成器" style="display:flex;align-items:center;gap:10px;"><div style="width:20px;height:20px;fill:currentColor">${ICONS.star}</div><span style="font-weight:600;">提示词生成器</span></a>`);
        menu.append(btn);
        btn.on('click', (e) => { e.preventDefault(); e.stopPropagation(); $('#extensionsMenu').fadeOut(200); addStyles($); createUI(); });
        console.log("✅ Hajimi Prompt Generator Loaded");
    }
    init();
})();

