function injectSettingsToAI(currentSettings) {
    updateVariablesWith(vars => {
        console.log('象牙塔QR [注入设置]: 开始将设置注入AI全局变量...', currentSettings);
        vars['字数总要求'] =
            `[${currentSettings.wordCount.min}-${currentSettings.wordCount.max}]字，[${currentSettings.paragraphCount.min}-${currentSettings.paragraphCount.max}]段`;
        if (currentSettings.aiMode === 'dialogue') {
            vars['talk'] =
                `\n- 停止所有创作任务，当前为元对话，象牙塔需以人格在正文中直接回应，禁止输出摘要\n- 你会铭记求索者的所有要求\n`;
        }
        else if (currentSettings.aiMode === 'outline') {
            vars['talk'] = `\n停止剧情，当前为元对话，象牙塔需听从用户指令，在正文中输出故事大纲，禁止输出摘要等其他内容\n`;
        }
        else if (currentSettings.aiMode === 'summary') {
            vars['talk'] =
                `\n停止所有创作任务，当前为元对话，象牙塔需听从用户指令，在正文中按总结格式输出大总结，禁止输出摘要等其他内容\n`;
        }
        else {
            vars['talk'] = '';
        }
        switch (currentSettings.perspective) {
            case 'third_person_omniscient':
                vars['叙述视角'] = settings.commands.perspective_third_person_omniscient;
                vars['char代词'] = '他/她/char_name';
                break;
            case 'third_person_limited':
                vars['叙述视角'] = settings.commands.perspective_third_person_limited;
                vars['char代词'] = '他/她/char_name';
                break;
            case 'first_person_limited':
                vars['叙述视角'] = settings.commands.perspective_first_person_limited;
                vars['char代词'] = '我';
                break;
        }
        switch (currentSettings.userPronoun) {
            case 'third_person':
                vars['user代词'] = settings.commands.userPronoun_third_person;
                break;
            case 'second_person':
                vars['user代词'] = settings.commands.userPronoun_second_person;
                break;
            case 'first_person':
                vars['user代词'] = settings.commands.userPronoun_first_person;
                break;
        }
        if (currentSettings.takeover === 'open') {
            vars['抢话开关'] = settings.commands.takeover_open;
        }
        else if (currentSettings.takeover === 'half_open') {
            vars['抢话开关'] = settings.commands.takeover_half_open;
        }
        else {
            vars['抢话开关'] = settings.commands.takeover_closed;
        }
        if (currentSettings.narrate === 'open') {
            vars['转述开关'] = settings.commands.narrate_open;
        }
        else {
            vars['转述开关'] = settings.commands.narrate_closed;
        }
        return vars;
    }, { type: 'global' });
    console.log('象牙塔QR [注入设置]: AI全局变量注入完成。');
}
