                .h-tab { cursor: pointer; padding: 6px 14px; color: var(--h-sub); border-radius: 4px; font-size:13px; font-weight:bold; transition:0.2s; display: flex; align-items: center; gap: 6px; }
                .h-tab:hover { background: rgba(139,30,30,0.1); color: var(--h-acc); }
                .h-tab.active { background: var(--h-acc); color: #F2E8D5; }
                .h-tab svg, .h-btn svg { width: 14px; height: 14px; fill: currentColor; }
                .h-close { cursor: pointer; width: 24px; height: 24px; fill: var(--h-acc); padding: 4px; transition:0.2s; }
                .h-close:hover { transform: scale(1.1); }
                .h-body { flex: 1; padding: 25px; overflow-y: auto; display: none; position: relative; }
                .h-body.active { display: block; animation: h-fade 0.2s; }
