                .h-group { margin-bottom: 18px; }
                .h-label { display: block; font-size: 12px; color: var(--h-sub); margin-bottom: 6px; font-weight: bold; text-transform: uppercase; }
                .h-input, .h-select { width: 100%; background: #FAF5E6; border: 1px solid var(--h-bd); color: var(--h-text); padding: 12px; border-radius: 4px; box-sizing: border-box; font-size: 14px; outline:none; transition:0.2s; }
                .h-input:focus, .h-select:focus { border-color: var(--h-acc); background: #FFF; }
                .h-btn { width: 100%; background: var(--h-acc); color: #F2E8D5; border: none; padding: 12px; border-radius: 6px; cursor: pointer; margin-top: 5px; font-weight: bold; font-size: 14px; transition:0.2s; display: flex; align-items: center; justify-content: center; gap: 8px; }
                .h-btn:hover { filter: brightness(1.1); transform: translateY(-1px); }
                .h-btn-sec { background: var(--h-bd); color: var(--h-text); }
                .h-btn-sec:hover { background: #B39F80; }
                .h-radio-group { display: flex; gap: 15px; }
                .h-mode-card { flex: 1; background: #FAF5E6; border: 2px solid var(--h-bd); border-radius: 8px; padding: 12px; cursor: pointer; transition: 0.2s; display: flex; flex-direction: column; gap: 6px; }
                .h-mode-card:hover { border-color: var(--h-acc); transform:translateY(-2px); }
                .h-mode-card.selected { border-color: var(--h-acc); background: #FFF0F0; }
                .h-mode-card svg { width: 18px; height: 18px; fill: var(--h-acc); }
