                .h-desc { font-size: 11px; color: var(--h-sub); }
                .h-lang-switch { display:flex; border: 1px solid var(--h-bd); border-radius: 6px; overflow:hidden; }
                .h-lang-btn { flex:1; padding:10px; background:#FAF5E6; color:var(--h-sub); cursor:pointer; font-size:12px; text-align:center; font-weight:bold; }
