                .h-history-item:hover { background: #FFF; border-left: 4px solid var(--h-acc); }
                .h-history-item.selected { background: #FFF0F0; border: 1px solid var(--h-acc); }
                .h-icon-box { width: 24px; height: 24px; background: var(--h-dark); border-radius: 4px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
                .h-icon-box svg { width: 14px; height: 14px; fill: var(--h-sub); }
                .h-actions { margin-left: auto; display: flex; gap: 8px; align-items: center; }
