                .h-item-btn:hover { opacity: 1; transform: scale(1.1); }
                .h-item-btn svg { width: 14px; height: 14px; fill: #7A6040; }
                .h-btn-dl:hover svg { fill: var(--h-acc); }
                .h-btn-del:hover svg { fill: #c0392b; }
                .h-selection-bar { position: absolute; bottom: 10px; left: 5%; width: 90%; background: var(--h-dark); border-radius: 30px; box-shadow: 0 5px 20px rgba(0,0,0,0.3); display: none; align-items: center; justify-content: space-between; padding: 10px 20px; box-sizing: border-box; z-index: 100; animation: slideUp 0.2s; border: 1px solid var(--h-bd); }
                .h-selection-bar.active { display: flex; }
                @keyframes slideUp { from{transform:translateY(20px);opacity:0} to{transform:translateY(0);opacity:1} }
                .h-sel-count { font-weight: bold; font-size: 13px; color: var(--h-text); }
                .h-sel-btns { display: flex; gap: 10px; }
                .h-btn-small { padding: 6px 12px; font-size: 12px; border-radius: 15px; border: none; cursor: pointer; font-weight: bold; }
                .h-accordion { border: 1px solid var(--h-bd); border-radius: 6px; overflow: hidden; margin-bottom: 10px; background: #FAF5E6; }
                .h-acc-head { padding: 12px 15px; background: var(--h-dark); cursor: pointer; display: flex; justify-content: space-between; align-items: center; font-weight: bold; font-size: 13px; color: var(--h-text); transition: 0.2s; }
                .h-acc-head:hover { background: #DCCFB0; }
                .h-acc-head svg { width: 16px; height: 16px; fill: var(--h-sub); transition: transform 0.3s; }
                .h-accordion.open .h-acc-head svg { transform: rotate(180deg); }
                .h-acc-body { display: none; padding: 15px; border-top: 1px solid var(--h-bd); background: #FAF5E6; }
                .h-slider-group { margin-bottom: 15px; }
                .h-slider-row { display: flex; align-items: center; gap: 10px; }
                .h-slider { flex: 1; -webkit-appearance: none; height: 4px; background: var(--h-bd); border-radius: 2px; outline: none; }
                .h-slider::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; background: var(--h-acc); border-radius: 50%; cursor: pointer; transition: 0.2s; }
                .h-slider::-webkit-slider-thumb:hover { transform: scale(1.2); }
                .h-slider-val { font-size: 12px; font-weight: bold; color: var(--h-acc); width: 35px; text-align: right; }
            </style>
        `);
    }

    function createUI() {
        const $ = getJQuery();
        $('#hajimi-ui-overlay').remove();
        currentResult = { cn: "", en: "" };
        selectionMode = false;
        selectedIndices.clear();

        const uiSettings = state.ui || { brightness: 100 };
        const isHuman = state.mode === 'human';
        const initialFilter = `brightness(${uiSettings.brightness}%)`;

        const html = `
            <div id="hajimi-ui-overlay" class="hajimi-overlay">
                <div class="hajimi-box" style="filter:${initialFilter}">
                    <div class="h-header">
                        <div style="fill:var(--h-acc);width:20px;height:20px;">${ICONS.star}</div>
                        <div class="h-title">提示词生成器</div>
                        <div class="h-tab active" data-tab="gen">${ICONS.star} 生成</div>
                        <div class="h-tab" data-tab="overview">${ICONS.history} 历史</div>
                        <div class="h-tab" data-tab="api">${ICONS.config} 配置</div>
                        <div class="h-close">${ICONS.close}</div>
                    </div>

                    <div id="tab-gen" class="h-body active">
                        <div class="h-group"><span class="h-label">模式选择</span>
                            <div class="h-radio-group">
                                <div class="h-mode-card ${isHuman?'selected':''}" data-val="human">
                                    <div class="h-header-row">${ICONS.human} 人话模式</div><div class="h-desc">细节扩充 / 通俗易懂</div>
                                </div>
                                <div class="h-mode-card ${!isHuman?'selected':''}" data-val="pro">
                                    <div class="h-header-row">${ICONS.pro} 专业模式</div><div class="h-desc">视觉转译 / 数值量化</div>
                                </div>
                            </div>
                        </div>
                        <textarea id="h-in" class="h-input" style="height:80px" placeholder="请输入您的要求..."></textarea>
                        <button id="h-go" class="h-btn">${ICONS.star} 点击生成 </button>
                        <div style="margin-top:15px;">
                            <div class="h-lang-switch">
                                <div id="btn-cn" class="h-lang-btn active">CN 中文</div><div id="btn-en" class="h-lang-btn">EN English</div>
                            </div>
                            <textarea id="h-out" class="h-input" style="height:150px; background:#fff;" placeholder="结果显示区..."></textarea>
                        </div>
                    </div>

                    <div id="tab-overview" class="h-body">
                        <div style="font-size:12px; color:var(--h-sub); margin-bottom:10px; display:flex; justify-content:space-between;">
                            <span>长按条目进入批量删除模式</span>
                        </div>
                        <div id="h-list"></div>
                        <div id="h-selection-bar" class="h-selection-bar">
                            <span class="h-sel-count">已选 0 项</span>
                            <div class="h-sel-btns">
                                <button id="h-sel-cancel" class="h-btn-small" style="background:var(--h-bd);color:var(--h-text)">取消</button>
                                <button id="h-sel-export" class="h-btn-small" style="background:#2ecc71;color:#fff">导出选中</button>
                                <button id="h-sel-del" class="h-btn-small" style="background:var(--h-acc);color:#fff">删除选中</button>
                            </div>
                        </div>
                    </div>

                    <div id="tab-api" class="h-body">
                        <div class="h-accordion">
                            <div class="h-acc-head">API 连接设置 ${ICONS.arrowDown}</div>
                            <div class="h-acc-body">
                                <div style="color:var(--h-acc);font-size:12px;margin-bottom:10px;">⚠️ 必须填写 API URL 和 Key 才能使用。</div>
                                <div class="h-group"><label class="h-label">API URL</label><input id="h-url" class="h-input" value="${state.apiUrl}" placeholder="https://api.openai.com/v1"></div>
                                <div class="h-group"><label class="h-label">API Key</label><input id="h-key" class="h-input" type="password" value="${state.apiKey}"></div>
                                <div class="h-group" style="display:flex;gap:10px;align-items:flex-end;">
                                    <div style="flex:1;"><label class="h-label">模型</label><select id="h-model" class="h-select"><option value="${state.model}">${state.model||'未选择'}</option></select></div>
                                    <button id="h-fetch" class="h-btn h-btn-sec" style="width:auto;margin:0;">${ICONS.fetch} 拉取</button>
                                </div>
                            </div>
                        </div>

                        <div class="h-accordion">
                            <div class="h-acc-head">页面视觉调节 ${ICONS.arrowDown}</div>
                            <div class="h-acc-body">
                                <div class="h-slider-group">
                                    <label class="h-label">整体亮度</label>
                                    <div class="h-slider-row">
                                        <input type="range" min="50" max="150" value="${uiSettings.brightness}" class="h-slider" id="h-bright-range">
                                        <span class="h-slider-val" id="h-bright-val">${uiSettings.brightness}%</span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <button id="h-save" class="h-btn" style="margin-top:20px;">${ICONS.save} 保存所有配置</button>
                    </div>
                </div>
            </div>
        `;

        $('body').append(html);

        const downloadTxt = (filename, content) => {
            const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            a.click();
            setTimeout(() => URL.revokeObjectURL(url), 100);
        };

        const formatExportContent = (items) => {
            return items.map(i => 
                `=========== ${new Date().toLocaleString()} ===========\n` +
                `[Mode]: ${i.mode}\n\n` +
                `>>> User Request:\n${i.raw}\n\n` +
                `>>> CN Prompt:\n${i.rcn}\n\n` +
                `>>> EN Prompt:\n${i.ren}\n`
            ).join('\n\n\n');
        };

        $('.h-close, #hajimi-ui-overlay').on('click', function(e) { if(e.target===this || $(this).hasClass('h-close')) $('#hajimi-ui-overlay').remove(); });
        $('.h-tab').on('click', function() { $('.h-tab,.h-body').removeClass('active'); $(this).addClass('active'); $('#tab-'+$(this).data('tab')).addClass('active'); });
        $('.h-mode-card').on('click', function() { $('.h-mode-card').removeClass('selected'); $(this).addClass('selected'); state.mode=$(this).data('val'); });
        $('#btn-cn').on('click', function() { $('.h-lang-btn').removeClass('active'); $(this).addClass('active'); $('#h-out').val(currentResult.cn||""); });
        $('#btn-en').on('click', function() { $('.h-lang-btn').removeClass('active'); $(this).addClass('active'); $('#h-out').val(currentResult.en||""); });

        $('.h-acc-head').on('click', function() {
            const parent = $(this).parent();
            parent.toggleClass('open');
            parent.find('.h-acc-body').slideToggle(200);
        });

        const updateUI = () => { $('.hajimi-box').css({ 'filter': `brightness(${state.ui.brightness}%)` }); };
        $('#h-bright-range').on('input', function() { state.ui.brightness = $(this).val(); $('#h-bright-val').text(state.ui.brightness + '%'); updateUI(); });

        const renderList = () => {
            const list = $('#h-list').empty();
            if(!state.history.length) return list.html('<div style="text-align:center;padding:20px;color:#7A6040">暂无记录</div>');
            state.history.forEach((item, index) => {
                const icon = item.mode==='human'?ICONS.human:ICONS.pro;
                const isSelected = selectedIndices.has(index);
                const checkIcon = selectionMode ? (isSelected ? `<div style="fill:var(--h-acc);margin-right:10px;width:18px;">${ICONS.check}</div>` : `<div style="width:18px;height:18px;border:2px solid var(--h-bd);border-radius:4px;margin-right:10px;box-sizing:border-box;"></div>`) : '';

                const el = $(`
                    <div class="h-history-item ${isSelected ? 'selected' : ''}" data-idx="${index}">
                        ${checkIcon}
                        <div class="h-icon-box">${icon}</div>
                        <div style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-left:5px;">${item.raw}</div>
                        ${!selectionMode ? `
                        <div class="h-actions">
                            <div class="h-item-btn h-btn-dl" title="导出TXT">${ICONS.download}</div>
                            <div class="h-item-btn h-btn-del" title="删除">${ICONS.trash}</div>
                        </div>` : ''}
                    </div>
                `);

                let pressTimer;
                el.on('mousedown touchstart', function(e) {
                    if (selectionMode) return;
                    pressTimer = setTimeout(() => { enterSelectionMode(index); }, 600);
                }).on('mouseup mouseleave touchend', function() { clearTimeout(pressTimer); });

                el.on('click', function(e) {
                    if (selectionMode) {
                        if (selectedIndices.has(index)) selectedIndices.delete(index); else selectedIndices.add(index);
                        updateSelectionBar(); renderList();
                    } else {
                        if ($(e.target).closest('.h-item-btn').length) return;
                        $('#h-in').val(item.raw); currentResult={cn:item.rcn,en:item.ren}; 
                        $('#btn-cn').click(); $('.h-tab[data-tab="gen"]').click(); 
                        $('.h-mode-card').removeClass('selected'); $(`.h-mode-card[data-val="${item.mode}"]`).addClass('selected'); state.mode=item.mode;
                    }
                });

                el.find('.h-btn-del').on('click', function(e) {
                    e.stopPropagation(); if(confirm('要删除这条记录喵？')) { state.history.splice(index, 1); saveState(); renderList(); }
                });

                el.find('.h-btn-dl').on('click', function(e) {
                    e.stopPropagation(); 
                    downloadTxt(`hajimi_prompt_${Date.now()}.txt`, formatExportContent([item]));
                });

                list.append(el);
            });
        };

        const enterSelectionMode = (idx) => { selectionMode = true; selectedIndices.add(idx); $('#h-selection-bar').addClass('active'); renderList(); updateSelectionBar(); };
        const exitSelectionMode = () => { selectionMode = false; selectedIndices.clear(); $('#h-selection-bar').removeClass('active'); renderList(); };
        const updateSelectionBar = () => { $('.h-sel-count').text(`已选中 ${selectedIndices.size} 项`); };

        $('#h-sel-cancel').on('click', exitSelectionMode);

        $('#h-sel-del').on('click', function() {
            if(!selectedIndices.size) return;
            if(confirm(`确定删除选中的 ${selectedIndices.size} 条记录喵？`)) {
                Array.from(selectedIndices).sort((a,b)=>b-a).forEach(i => state.history.splice(i, 1));
                saveState(); exitSelectionMode();
            }
        });

        $('#h-sel-export').on('click', function() {
            if(!selectedIndices.size) return;
            const items = Array.from(selectedIndices).sort((a,b)=>a-b).map(i => state.history[i]);
            downloadTxt(`hajimi_batch_prompts_${Date.now()}.txt`, formatExportContent(items));
            exitSelectionMode();
        });

        renderList();

        $('#h-fetch').on('click', async () => {
            const u=$('#h-url').val().replace(/\/$/,''), k=$('#h-key').val();
            if(!u || !k) return alert('请先填写 URL 和 Key');
            try { const r=await fetch(`${u}/models`,{headers:{'Authorization':`Bearer ${k}`}}); const d=await r.json(); 
            if(d.data) { const s=$('#h-model').empty(); d.data.forEach(m=>s.append(`<option value="${m.id}">${m.id}</option>`)); if(state.model)s.val(state.model); }
            } catch(e) { alert(e.message); }
        });

        $('#h-save').on('click', () => { state.apiUrl=$('#h-url').val(); state.apiKey=$('#h-key').val(); state.model=$('#h-model').val(); saveState(); alert('已保存'); });

        $('#h-go').on('click', async () => {
            const raw=$('#h-in').val(); if(!raw) return;
            if(!state.apiUrl || !state.apiKey) return alert('请前往配置页填写 API URL 和 Key！');
            $('#h-go').text('生成中...').prop('disabled',true);

            const sys = state.mode==='human' 
                ? `You are a precise prompt refining assistant. Task: Summarize ALL points and details from the user's request, expand moderately, and generate a concise, easy-to-understand prompt. Rules: 1. Cover ALL user requirements (summarize & expand). 2. Be CONCISE and PRECISE. Avoid wordiness. 3. Use natural language suitable for AI generation. 4. Output ONLY the raw prompt content. No "Role:" labels. 5. JSON Format: { "cn": "...", "en": "..." }`
                : `You are a Senior UI/UX Designer & Prompt Engineer. Task: Extract core needs and details, refining them into a PROFESSIONAL UI DESIGN PROMPT. Rules: 1. QUANTIFY inputs using professional terminology (Visual Hierarchy, Grid, Hex Codes, Padding, Typography, Texture). 2. ABSOLUTELY FORBIDDEN: Short/Single-sentence outputs. 3. If user input is sparse/vague, YOU MUST EXPAND IT with relevant professional details (add matching colors, layout styles, textures) to make it complete. 4. Focus on structure, layout, and visual properties. 5. OUTPUT ONLY RAW DATA. NO labels. 6. JSON Format: { "cn": "...", "en": "..." }`;

            const msgs = [{role:'system',content:sys},{role:'user',content:raw}];
            try {
                const r = await fetch(`${state.apiUrl.replace(/\/$/,'')}/chat/completions`, {
                    method:'POST', headers:{'Content-Type':'application/json','Authorization':`Bearer ${state.apiKey}`},
                    body: JSON.stringify({model:state.model||'gpt-3.5-turbo', messages:msgs})
                });
                const d=await r.json();
                let txt = d.choices?.[0]?.message?.content; if(!txt) throw new Error("API No Content");
                const parse = (t) => { try{return JSON.parse(t)}catch(e){const m=t.match(/\{[\s\S]*\}/);if(m)return JSON.parse(m[0]);throw e;} };
                const safeStr = (v) => (typeof v==='object'&&v)?JSON.stringify(v,null,2).replace(/[\{\}\"]/g,'').trim():v;
                const j = parse(txt);
                currentResult = { cn: safeStr(j.cn)||"Error CN", en: safeStr(j.en)||"Error EN" };
                $('#btn-cn').click();
                state.history.unshift({raw, rcn:currentResult.cn, ren:currentResult.en, mode:state.mode});
                if(state.history.length>30) state.history.pop(); saveState(); renderList();
            } catch(e) { alert('错误: '+e.message); }
            $('#h-go').html(`${ICONS.star} 点击生成 `).prop('disabled',false);
        });
    }

    function init() {
        const $ = getJQuery(); if(!$) return setTimeout(init, 500);
        const menu = $('#extensionsMenu'); if(!menu.length) return setTimeout(init, 500);
        deepClean();
        const btn = $(`<a id="hajimi-trigger-btn" class="list-group-item" href="#" title="提示词生成器" style="display:flex;align-items:center;gap:10px;"><div style="width:20px;height:20px;fill:currentColor">${ICONS.star}</div><span style="font-weight:600;">提示词生成器</span></a>`);
        menu.append(btn);
        btn.on('click', (e) => { e.preventDefault(); e.stopPropagation(); $('#extensionsMenu').fadeOut(200); addStyles($); createUI(); });
        console.log("✅ Hajimi Prompt Generator Loaded");
    }
    init();
})();

