<body>
    <div class="ghost-calendar-app" id="ghostCalendarApp">
        <div class="theme-toggle" onclick="window.toggleGhostTheme()" title="切换日/夜模式"><span id="themeIcon">☾</span>
        </div>
        <div class="ghost-header"><span class="ghost-title">日程卷</span><span class="ghost-subtitle">呈 <user> 台鉴 · 古风卷轴版</span></div>
        <div class="ghost-action-bar">
            <div class="ghost-action-copy">
                <div class="ghost-action-title">剧情推进 <span class="ghost-selected-count" id="ghostSelectionCount">0</span></div>
                <div class="ghost-action-hint" id="ghostSelectionHint">点击每条日程右侧“加入剧情”即可多选，再统一写入输入框。</div>
            </div>
            <div class="ghost-action-buttons">
                <button class="ghost-action-btn" id="ghostClearSelectionBtn" type="button" disabled>清空选择</button>
                <button class="ghost-action-btn primary" id="ghostComposeBtn" type="button" disabled>推进已选日程</button>
            </div>
        </div>
        <div class="ghost-scroller" id="ghost-scroller-switch"></div>
        <div class="ghost-list" id="ghost-list-switch"></div>
        <div class="ghost-footer" id="ghostFooterStatus">选择一条或多条日程后，点击上方按钮写入输入框，不会自动发送。</div>
    </div>
    <script type="text/plain" id="calendar-raw-data-switch">$1</script>
    <script>
        (function () {
            // === 1. 主题切换逻辑 ===
            const app = document.getElementById('ghostCalendarApp');
            const icon = document.getElementById('themeIcon');
            const STORAGE_KEY = 'ghost-calendar-theme';
            function initTheme() {
                const savedTheme = localStorage.getItem(STORAGE_KEY);
                if (savedTheme === 'night') { app.classList.add('night-mode'); icon.textContent = '☀'; }
                else { app.classList.remove('night-mode'); icon.textContent = '☾'; }
            }
            window.toggleGhostTheme = function () {
                app.classList.toggle('night-mode');
                const isNight = app.classList.contains('night-mode');
                icon.textContent = isNight ? '☀' : '☾';
                localStorage.setItem(STORAGE_KEY, isNight ? 'night' : 'day');
            };
            initTheme();

            // === 2. 数据解析与渲染逻辑 (兼容5和6字段) ===
            const rawDataContainer = document.getElementById('calendar-raw-data-switch');
            if (!rawDataContainer) return;
            const rawString = rawDataContainer.textContent.trim();
            const lines = rawString.split(/\r?\n/);
            const calendarData = [];
            let currentDayObj = null;

            lines.forEach(line => {
                line = line.trim();
                if (!line) return;
                if (line.startsWith('Date:')) {
                    const parts = line.replace('Date:', '').split('|').map(s => s.trim());
                    if (parts.length >= 1) { currentDayObj = { dateStr: parts[0], dayName: parts[1] || '', events: [] }; calendarData.push(currentDayObj); }
                }
                else if (line.startsWith('Event:') && currentDayObj) {
                    const parts = line.replace('Event:', '').split('|').map(s => s.trim());
                    // *** 修改: 兼容5字段和6字段 ***
                    if (parts.length >= 5) { // 只要有5个基本字段就进行处理
                        currentDayObj.events.push({
                            type: parts[0], title: parts[1], description: parts[2], time: parts[3], location: parts[4],
                            npcAction: parts[5] || '' // 如果第6个字段不存在，则赋值为空字符串
                        });
                    }
                }
            });

            const scroller = document.getElementById('ghost-scroller-switch');
            const eventList = document.getElementById('ghost-list-switch');
            const footerStatus = document.getElementById('ghostFooterStatus');
            const selectionCount = document.getElementById('ghostSelectionCount');
            const selectionHint = document.getElementById('ghostSelectionHint');
            const composeBtn = document.getElementById('ghostComposeBtn');
            const clearSelectionBtn = document.getElementById('ghostClearSelectionBtn');
            const selectedEventIds = new Set();
            const eventLookup = new Map();
            let activeDayData = null;

            function getColorByType(type) { switch (type) { case 'world': return 'var(--c-world)'; case 'major': return 'var(--c-major)'; case 'user': return 'var(--c-user)'; case 'character': return 'var(--c-char)'; default: return 'currentColor'; } }
            function translateType(type) { switch (type.toLowerCase()) { case 'world': return '世界'; case 'major': return '重要'; case 'user': return '日常'; case 'character': return '羁绊'; default: return '其他'; } }
            function setStatus(text, isError = false) {
                if (!footerStatus) return;
                footerStatus.textContent = text;
                footerStatus.style.opacity = isError ? '0.72' : '0.42';
            }
            function formatEventPrompt(ev) {
                const dateLabel = `${ev.dateStr}${ev.dayName ? ` ${ev.dayName}` : ''}`.trim();
                const npcLabel = ev.npcAction && ev.npcAction.trim() !== '' ? `；补充信息是：${ev.npcAction}` : '';
                return `${dateLabel} ${ev.time}，在${ev.location}进行「${ev.title}」这项${translateType(ev.type)}日程，主要内容是：${ev.description}${npcLabel}。`;
            }
            function buildInputText(events) {
                if (!events || events.length === 0) return '';
                if (events.length === 1) {
                    const ev = events[0];
                    const dateLabel = `${ev.dateStr}${ev.dayName ? ` ${ev.dayName}` : ''}`.trim();
                    const npcLabel = ev.npcAction && ev.npcAction.trim() !== '' ? `补充信息是：${ev.npcAction}。` : '';
                    return [
                        `请将剧情时间推进到${dateLabel} ${ev.time}，从「${ev.title}」这项${translateType(ev.type)}日程开始展开。`,
                        `当前地点是${ev.location}，该日程的主要内容是：${ev.description}。`,
                        npcLabel
                    ].filter(Boolean).join('');
                }
                return [
                    '请将本次剧情从以下已选日程开始推进，并按时间顺序自然衔接展开：',
                    ...events.map((ev, index) => `${index + 1}. ${formatEventPrompt(ev)}`),
                    '请默认从第一项日程开始推进时间，并把这些安排整合成连贯的剧情过程。'
                ].join('\n');
            }
            function getSelectedEvents() {
                return Array.from(selectedEventIds)
                    .map(id => eventLookup.get(id))
                    .filter(Boolean)
                    .sort((a, b) => a.dayIndex - b.dayIndex || a.eventIndex - b.eventIndex);
            }
            function updateSelectionUI() {
                const count = selectedEventIds.size;
                if (selectionCount) selectionCount.textContent = String(count);
                if (composeBtn) {
                    composeBtn.disabled = count === 0;
                    composeBtn.textContent = count > 0 ? `推进已选日程 (${count})` : '推进已选日程';
                }
                if (clearSelectionBtn) clearSelectionBtn.disabled = count === 0;
                if (selectionHint) {
                    selectionHint.textContent = count > 0
                        ? `已选 ${count} 条日程，点击右侧按钮即可整理为一段剧情推进提示。`
                        : '点击每条日程右侧“加入剧情”即可多选，再统一写入输入框。';
                }
            }
            async function fallbackSetInput(text) {
                try {
                    const hostWindow = window.parent && window.parent !== window ? window.parent : window;
                    const hostDocument = hostWindow.document;
                    const selectors = ['#send_textarea', 'textarea#send_textarea', 'textarea[name="user_input"]', '#chat-input textarea', 'textarea'];
                    let inputEl = null;

                    selectors.some(selector => {
                        const found = Array.from(hostDocument.querySelectorAll(selector)).find(node =>
                            !node.disabled && !node.readOnly && (node.offsetParent !== null || selector === 'textarea')
                        );
                        if (found) {
                            inputEl = found;
                            return true;
                        }
                        return false;
                    });

                    if (!inputEl) return false;

                    inputEl.focus();
                    if (inputEl.tagName === 'TEXTAREA' || inputEl.tagName === 'INPUT') {
                        const proto = inputEl.tagName === 'TEXTAREA'
                            ? hostWindow.HTMLTextAreaElement.prototype
                            : hostWindow.HTMLInputElement.prototype;
                        const descriptor = Object.getOwnPropertyDescriptor(proto, 'value');
                        if (descriptor && descriptor.set) descriptor.set.call(inputEl, text);
                        else inputEl.value = text;
                    } else if (inputEl.isContentEditable) {
                        inputEl.textContent = text;
                    }

                    inputEl.dispatchEvent(new hostWindow.Event('input', { bubbles: true }));
                    inputEl.dispatchEvent(new hostWindow.Event('change', { bubbles: true }));
                    return true;
                } catch (error) {
                    console.warn('ghost-calendar fallback set input failed:', error);
                    return false;
                }
            }
            async function writeToUserInput(text, title, count = 1) {
                try {
                    if (typeof triggerSlash === 'function') {
                        await triggerSlash('/setinput ' + text);
                        setStatus(count > 1 ? `已将 ${count} 条已选日程整理后写入输入框，未自动发送。` : `已将「${title || '未命名日程'}」写入输入框，未自动发送。`);
                        return;
                    }
                } catch (error) {
                    console.warn('ghost-calendar triggerSlash failed:', error);
                }

                const ok = await fallbackSetInput(text);
                if (ok) setStatus(count > 1 ? `已将 ${count} 条已选日程整理后写入输入框，未自动发送。` : `已将「${title || '未命名日程'}」写入输入框，未自动发送。`);
                else setStatus('未找到输入框，未能写入日程内容。', true);
            }

            function render() {
                scroller.innerHTML = '';
                scroller.classList.toggle('spread-layout', calendarData.length > 0 && calendarData.length <= 8);
                calendarData.forEach((day, index) => {
                    const card = document.createElement('div');
                    card.className = `ghost-date-item ${index === 0 ? 'active' : ''}`;
                    const dateParts = day.dateStr.split('/');
                    const dayNum = dateParts[dateParts.length - 1];
                    let dotsHtml = '';
                    day.events.forEach(ev => { const color = getColorByType(ev.type); dotsHtml += `<div class="ghost-dot" style="background-color: ${color}"></div>`; });
                    card.innerHTML = `<span class="ghost-day-name">${day.dayName}</span><span class="ghost-day-num">${dayNum}</span><div class="ghost-dots">${dotsHtml}</div>`;
                    card.onclick = () => { scroller.querySelectorAll('.ghost-date-item').forEach(c => c.classList.remove('active')); card.classList.add('active'); renderEvents(day); };
                    scroller.appendChild(card);
                });
                if (calendarData.length > 0) renderEvents(calendarData[0]); else eventList.innerHTML = '<div class="ghost-empty">空空如也</div>';
            }

            function renderEvents(dayData) {
                activeDayData = dayData;
                eventList.innerHTML = '';
                if (dayData.events.length === 0) { eventList.innerHTML = '<div class="ghost-empty">没有安排？好好休息吧</div>'; return; }
                dayData.events.forEach(ev => {
                    const details = document.createElement('details');
                    details.className = `ghost-event-details type-${ev.type}`;
                    details.classList.toggle('selected', selectedEventIds.has(ev.id));
                    let typeLabel = translateType(ev.type);
                    const isSelected = selectedEventIds.has(ev.id);

                    // *** 修改: 动态生成内容区域 ***
                    let contentHtml = `<div class="ghost-event-desc">${ev.description}</div>`;
                    // 只有当 npcAction 存在且不为空时，才添加这部分HTML
                    if (ev.npcAction && ev.npcAction.trim() !== '') {
                        contentHtml += `<div class="ghost-event-npc-action">${ev.npcAction}</div>`;
                    }

                    details.innerHTML = `
                        <summary class="ghost-event-summary">
                            <div class="ghost-event-topline">
                                <div class="ghost-event-meta"><span>${ev.time}</span><span>•</span><span>${typeLabel}</span></div>
                                <button class="ghost-select-btn ${isSelected ? 'selected' : ''}" type="button" aria-pressed="${isSelected ? 'true' : 'false'}">${isSelected ? '已选中' : '加入剧情'}</button>
                            </div>
                            <div class="ghost-event-title">${ev.title}</div>
                            <div class="ghost-event-loc">@ ${ev.location}</div>
                        </summary>
                        <div class="ghost-event-content-wrapper">${contentHtml}</div>
                    `;
                    const selectBtn = details.querySelector('.ghost-select-btn');
                    selectBtn.addEventListener('click', event => {
                        event.preventDefault();
                        event.stopPropagation();
                        if (selectedEventIds.has(ev.id)) selectedEventIds.delete(ev.id);
                        else selectedEventIds.add(ev.id);
                        details.classList.toggle('selected', selectedEventIds.has(ev.id));
                        selectBtn.classList.toggle('selected', selectedEventIds.has(ev.id));
                        selectBtn.setAttribute('aria-pressed', selectedEventIds.has(ev.id) ? 'true' : 'false');
                        selectBtn.textContent = selectedEventIds.has(ev.id) ? '已选中' : '加入剧情';
                        updateSelectionUI();
                    });
                    eventList.appendChild(details);
                });
            }

            if (composeBtn) {
                composeBtn.addEventListener('click', () => {
                    const selectedEvents = getSelectedEvents();
                    if (selectedEvents.length === 0) return;
                    const leadTitle = selectedEvents.length === 1 ? selectedEvents[0].title : `${selectedEvents.length} 条已选日程`;
                    writeToUserInput(buildInputText(selectedEvents), leadTitle, selectedEvents.length);
                });
            }
            if (clearSelectionBtn) {
                clearSelectionBtn.addEventListener('click', () => {
                    selectedEventIds.clear();
                    updateSelectionUI();
                    if (activeDayData) renderEvents(activeDayData);
                    setStatus('已清空已选日程。');
                });
            }

            calendarData.forEach((day, dayIndex) => {
                day.dayIndex = dayIndex;
                day.events.forEach((ev, eventIndex) => {
                    ev.id = `${dayIndex}-${eventIndex}`;
                    ev.dayIndex = dayIndex;
                    ev.eventIndex = eventIndex;
                    ev.dateStr = day.dateStr;
                    ev.dayName = day.dayName;
                    eventLookup.set(ev.id, ev);
                });
            });

            updateSelectionUI();
            render();
        })();
    </script>
</body>

</html>

