            position: relative;
            display: inline-block;
            max-width: 90%;
            text-align: left; /* 这种风格左对齐或两端对齐更好看 */
            margin-top: 5px;
            background: transparent; /* 去除背景 */
            border: none; /* 去除边框 */
        }

        /* 首字下沉/浮起效果 */
        .novel-preface::first-letter {
            float: none; /* 取消浮动 */
            font-size: 2.0em; /* 稍微大一点即可 */
            vertical-align: baseline; /* 底部对齐 */
            margin-right: 2px;
            font-family: 'Playfair Display', serif;
            color: var(--novel-accent);
