    <!-- 数据挂载区 (SillyTavern参数) -->
    <div id="raw-options-data">$1</div>

    <script>
        document.addEventListener("DOMContentLoaded", function () {
            const body = document.body;

            // --- 样式匹配引擎 ---
            let styleName = 'v2'; // 默认样式
            try {
                const TH = window.TavernHelper || window.parent.TavernHelper;
                if (TH) {
                    const presetName = TH.getLoadedPresetName();
                    const presetInUse = TH.getPreset(presetName);
                    // console.log("当前已加载的预设：", presetName, presetInUse);
                    if (presetInUse) {
                        const regexes = presetInUse.extensions.regex_scripts || [];
                        // console.log("当前已加载的正则列表：", regexes);
                        const allEnabledNames = [...regexes]
                            .filter(r => r && r.enabled)
                            .map(r => r.script_name || '');

                        if (allEnabledNames.some(name => name.includes("新版小说标题3"))) {
                            styleName = 'ao3';
                            // console.log("检测到启用小说标题AO3样式，已应用对应的分支选择器样式");
                        } else if (allEnabledNames.some(name => name.includes("新版小说标题2"))) {
                            styleName = 'v1';
                            // console.log("检测到启用小说标题2样式，已应用对应的分支选择器样式");
                        }
                    }
                }
            } catch (e) {
                console.warn("无法通过正则获取当前样式，将使用默认样式(v2)", e);
            }

            document.getElementById("selector-wrapper").classList.add('style-' + styleName);

            // --- 日夜间模式同步逻辑 ---
            function applyThemePreference() {
                // 根据当前生效的样式，针对性地监听和调取对应的环境偏好
                const key = styleName === 'ao3' ? 'ao3_theme'
                    : styleName === 'v1' ? 'novel_theme_preference'
                        : 'novel_theme_preference_v2';

                const savedPref = localStorage.getItem(key);
                let isDark = (savedPref === 'night');

                // 为了兼容 v2 原版的逻辑，如果没有设置过，默认应用深色
                if (styleName === 'v2' && !savedPref) isDark = true;

                if (isDark) {
                    body.classList.remove('theme-light');
                    body.classList.add('theme-dark');
                } else {
                    body.classList.remove('theme-dark');
                    body.classList.add('theme-light');
                }
            }

            // --- V2 动态主题色同步逻辑 ---
            function applyV2ThemeColor() {
                // 原版色彩变量在新增的两套样式中无视
                if (styleName !== 'v2') return;

                const savedColor = localStorage.getItem('novel_theme_color_v2');
                if (savedColor) {
                    const rgb = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(savedColor);
                    if (rgb) {
                        const wrapper = document.getElementById("selector-wrapper");
                        if (wrapper) {
                            wrapper.style.setProperty('--night-accent-hex', savedColor);
                            wrapper.style.setProperty('--night-r', parseInt(rgb[1], 16));
                            wrapper.style.setProperty('--night-g', parseInt(rgb[2], 16));
                            wrapper.style.setProperty('--night-b', parseInt(rgb[3], 16));
                        }
                    }
                }
            }

            // 初次渲染应用
            applyThemePreference();
            applyV2ThemeColor();

            // 监听 localStorage 的变化，实现与其他组件的实时同步
            window.addEventListener('storage', function (e) {
                if (['ao3_theme', 'novel_theme_preference', 'novel_theme_preference_v2'].includes(e.key)) {
                    applyThemePreference();
                }
                if (e.key === 'novel_theme_color_v2') applyV2ThemeColor();
            });

            // 拦截同页面的存储变化，确保跨组件(内嵌式)交互也能响应
            const originalSetItem = localStorage.setItem;
            localStorage.setItem = function (key, val) {
                originalSetItem.apply(this, arguments);
                if (['ao3_theme', 'novel_theme_preference', 'novel_theme_preference_v2'].includes(key)) {
                    applyThemePreference();
                }
                if (key === 'novel_theme_color_v2') applyV2ThemeColor();
            };

            // --- 选项渲染逻辑 ---
            const rawNode = document.getElementById("raw-options-data");
            const root = document.getElementById("options-container");

            if (rawNode && root) {
                root.innerHTML = '';
                // 解决可能存在的HTML转义问题，并按行分割
                const rawText = rawNode.innerHTML.replace(/<br\s*\/?>/gi, '\n').replace(/</g, '<').replace(/>/g, '>');
                const lines = (rawNode.textContent || rawText).trim().split(/\r?\n/).filter(s => s.trim() !== "");

                lines.forEach((line) => {
                    let text = line.trim();
                    const match = text.match(/^([A-Z])\.\s*(.*)$/i);

                    // 兼容原来的格式，如果存在 A. 则隐去字母
                    if (match) { text = match[2]; }
                    if (!text) return;

                    const item = document.createElement("div");
                    item.className = "clickable-text";
                    item.setAttribute("data-action", text);

                    const li = document.createElement("li");
                    if (styleName === 'ao3') {
                        li.style.listStyle = "none";
                    }
                    li.textContent = text;
                    item.appendChild(li);

                    item.addEventListener("click", function (e) {
                        e.stopPropagation();
                        // 移除兄弟节点的选中态
                        root.querySelectorAll('.clickable-text').forEach(el => el.classList.remove('selected'));
                        this.classList.add('selected');

                        const payload = this.getAttribute("data-action");
                        try {
                            const t = window.parent.document.querySelector("#send_textarea");
                            const n = window.parent.triggerSlash;
                            if (t) {
                                const v = t.value + payload;
                                if (n) { n(`/setinput ${v}`); }
                                else { t.value = v; t.dispatchEvent(new Event("input", { bubbles: true })); }
                            } else if (n) { n(`/setinput ${payload}`); }
                        } catch (err) {
                            console.error("Failed to send text to SillyTavern input:", err);
                        }
                    });
                    root.appendChild(item);
                });
            }
        });
    </script>
</body>

