            justify-content: center;
        }

        /* --- UTILS --- */
        .hidden-scrollbar::-webkit-scrollbar { display: none; }
        .hidden-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

        /* --- SWISS ISLAND CONTAINER --- */
        .swiss-island {
            --spring-easing: cubic-bezier(0.19, 1, 0.22, 1);
            position: relative;
            background-color: #050505;
            color: white;
            overflow: hidden;
            z-index: 50;
            transition: width 0.6s var(--spring-easing), height 0.6s var(--spring-easing), border-radius 0.6s var(--spring-easing), transform 0.2s ease;

            --mouse-x: 50%;
            --mouse-y: 50%;
        }

        /* States */
        .swiss-island.collapsed { width: 240px; height: 60px; border-radius: 999px; cursor: pointer; }
        .swiss-island.collapsed:hover { transform: scale(1.05); }
        .swiss-island.collapsed:active { transform: scale(0.95); }
        .swiss-island.expanded { width: 100%; height: 680px; border-radius: 32px; cursor: default; }

        /* --- GLOW EFFECT --- */
        .swiss-island.collapsed::before {
            content: "";
            position: absolute; inset: 0; border-radius: inherit;
            background: radial-gradient(200px circle at var(--mouse-x) var(--mouse-y), rgba(255, 255, 255, 0.15), transparent 100%);
            opacity: 0; transition: opacity 0.5s ease; pointer-events: none; z-index: 2;
        }
        .swiss-island.collapsed:hover::before { opacity: 1; }

        /* --- BUBBLE TRIGGER ZONE --- */
        .bubble-trigger-zone {
            position: absolute;
            top: 120px;
            left: 30px;
            right: 30px;
            bottom: 150px;
            z-index: 15;
            cursor: pointer;
        }

        /* --- SPEECH BUBBLE STYLES --- */
        .speech-bubble {
            position: absolute;
            padding: 12px 18px;
