        }
        const c = settings.ballColor || { r: 240, g: 240, b: 240, a: 0.6 };
        const grd = ctx.createLinearGradient(0, 0, w, 0);
        grd.addColorStop(0, `rgba(${c.r},${c.g},${c.b},0)`);
        grd.addColorStop(1, `rgba(${c.r},${c.g},${c.b},1)`);
        ctx.fillStyle = grd;
